package com.bte.service;
import com.bte.entity.*;import com.bte.dto.*;import com.bte.enums.*;import com.bte.exception.*;import java.util.*;
public final class RoundScoreRules {
 private RoundScoreRules(){}
 public static List<MatchPlayerScore> validate(Tournament t,List<Registration> entries,List<MatchRankingRequest> rankings){if(t.getPlannedRounds()==0)return new ArrayList<>();var paid=entries.stream().filter(r->r.getPaymentStatus()==PaymentStatus.PAID).toList();if(rankings.size()!=paid.size())throw new BadRequestException("Record every paid team's score for this round");var seen=new HashSet<Long>();var ranks=new HashSet<Integer>();var scores=new ArrayList<MatchPlayerScore>();for(var row:rankings){var entry=paid.stream().filter(r->Objects.equals(row.playerUserId(),r.getOwnerUserId()) || Objects.equals(row.playerUserId(),r.getGuestAccountId())).findFirst().orElseThrow(()->new BadRequestException("Only paid team captains may be scored"));if(!seen.add(entry.getId()) || row.rank()==null || row.rank()<1 || row.rank()>paid.size() || !ranks.add(row.rank()))throw new BadRequestException("Use each team once with unique ranks 1 through team count");if(row.placementPoints()==null || row.placementPoints()<0 || row.placementPoints()>10000 || row.playerKills()==null)throw new BadRequestException("Placement points and individual kills are required");if(entry.getSquadMembers().size()!=t.getSquadSize())throw new BadRequestException("Complete the squad roster before recording scores");var ids=new HashSet<Long>();ids.add(entry.getOwnerUserId());entry.getSquadMembers().stream().skip(1).forEach(m->ids.add(m.getWalletUserId()));if(ids.contains(null) || !row.playerKills().keySet().equals(ids))throw new BadRequestException("Record kills for every member of this team, using their wallet account ID");int kills=0;for(var id:ids){Integer value=row.playerKills().get(id);if(value==null || value<0 || value>100000)throw new BadRequestException("Invalid individual kill count");kills=Math.addExact(kills,value);scores.add(new MatchPlayerScore(id,entry.getOwnerUserId(),value));}if(row.kills()==null || kills!=row.kills())throw new BadRequestException("Team kills must equal the sum of individual kills");}return scores;}
 public static List<MatchRanking> rankings(List<MatchRankingRequest> request){return request.stream().sorted(Comparator.comparing(MatchRankingRequest::rank)).map(row->{var r=new MatchRanking(row.playerUserId(),row.rank(),row.kills(),row.teamName());r.setPlacementPoints(row.placementPoints()==null?0:row.placementPoints());return r;}).collect(java.util.stream.Collectors.toCollection(java.util.ArrayList::new));}
}
